namespace StardewCodexChat.UI;

/// <summary>Help-page copy; headings are drawn with a bold font, not Markdown.</summary>
internal static class HelpContent
{
    internal static readonly (string Heading, string Body)[] Sections = {
        ("Stardew Copilot 使用帮助",
            "Stardew Copilot 是游戏内的星露谷助手。你可以询问游戏攻略、结合当前存档获取建议，也可以用待办清单记录想做的事。\n当前版本适用于 macOS、Stardew Valley 1.6.15 和 SMAPI 4.5.2。"),
        ("打开与关闭",
            "进入存档后，按 Enter 或点击右下角能量条上方的圆形按钮打开助手。单人模式下，在背包、地图、箱子、商店等菜单中，Enter未被占用时也可直接呼出。助手直接叠加在原菜单上，旧菜单不会关闭或释放。按 Esc 或点击右上角 × 只移除助手，回到原菜单。\n助手打开期间单人游戏时间暂停，关闭后恢复原有暂停状态；若底层菜单原本就暂停游戏，则继续暂停。AI仍可在后台回答。\n输入文字、改键或Enter已有确认用途时，优先保留原操作；不打断读存档、结算、全屏小游戏和场景过渡。联机不扩展叠加入口，也不强制暂停世界。\n首次使用未配置 Key 时会先显示配置弹窗，粘贴 DeepSeek API Key 并确认后即可使用；Key 加密保存在 Mod 文件夹内。"),
        ("关于对话",
            "在输入框中写下问题，按 Enter 或点击发送按钮提交。可以直接问攻略问题，例如“煤炭在哪里获取？”，也可以结合存档提问，例如“我有哪些作物还没浇水？”。助手支持连续追问，同一存档会一直沿用同一对话，直到用户使用 /clearchat 指令清除对话记录并新开对话。不同存档的对话记录会分别保存。对话较长时，助手会自动压缩上下文。\n游戏机制问题会优先检索本地 Wiki 知识库，不足或过期时联网补充；Wiki 仍不足时会扩大到全网搜索并读取正文，必要时换关键词继续查找；模型发现缓存不足时可以重新联网检索，回答附带浅蓝色编号来源，鼠标悬停可查看网址，完全使用缓存的回答不显示参考；资料不足会说明无法核实。\n当回答用户的问题需要当前游戏状态时，模型会进行主动查询。目前可以查询日期、时间、天气、运气、生命、体力、金钱、技能及所在地点，也可以查看背包和装备、当前任务、NPC 信息、作物、加工机器，以及普通箱子和冰箱中的物品。\n例如可以问：\n“我的铜矿放在哪个箱子里？”\n“阿比盖尔现在在哪里？”\n“农场有哪些作物可以收获？”\n“有哪些机器的产物可以收取？”\n“我有哪些快到期的任务？”"),
        ("截图分析",
            "输入 /screen 加上问题，例如“/screen 帮我看看背包里有哪些值得出售的物品”。请先打开要分析的背包、箱子或其他界面，再按 Enter 叠加助手。截图会保留底层游戏菜单，排除助手自身窗口；只读取游戏画面，不截整个桌面，也不需要系统录屏权限。\n先将原图缩为快速预览交给模型，细节不够时从保留的原图扩大边界后裁剪；一次最多3个局部图，合并发送，局部阶段不重复发送完整画面。必要时允许再截一次当前画面；新画面仍可裁剪，最多8轮处理、8次游戏明细与2次机制检索，整体最多约180秒，也受个人超时配置影响。\n截图模式会结合当前存档的对话摘要、近期对话与本次即时游戏状态。每次新读概要和待办，还可查询背包、任务、NPC等明细；历史状态不代替当前数据。Wiki结论用正文浅蓝色编号标注实际来源，悬停查看网址；截图和状态用文字注明来自游戏。\n原图和裁剪图仅在本次请求的内存中保留，不写入文件或历史对话；图片会发送给 DeepSeek，图片输入按服务计费。文字问答仍按当前存档保存。当前需要 deepseek-flash；其他模型请先修改 config.json 的 Model 并重启。\n模型会区分图片清晰度不足与游戏画面本身没显示信息。画面未显示的信息会先用现有只读查询补全；接口未提供时需你自行打开或悬停后重新提问，助手不会自动操作游戏；图标、数量、品质或售价看不清时应说明不确定。Esc 关闭后分析仍在后台继续，稍后 Enter 可回来查看；切换存档会取消。暂不支持分屏。"),
        ("关于待办",
            "待办列表只显示最新 30 条记录，更早的记录仍保存在文件中。每个存档最多保存 200 条，每条最多 300 个字符。待办会按存档自动保存，重进游戏后恢复。\n待办可以与对话进行联动，助手能够读取待办及完成状态，并在用户要求时添加新待办。可以在对话中问“我还有哪些待办没完成？”，或者说“帮我记下明天去找罗宾”。"),
        ("特殊指令",
            "特殊指令需要在“对话”输入框中输入，并以 / 开头。空输入框输入 / 会显示全部指令，用上下键选择、回车补全，也可点击条目；补全不会立即执行。\n/clearchat | 清除当前存档的全部历史对话\n/cleartodo | 清除当前存档的全部待办\n/resetkey | 重新配置 API Key\n/screen 你的问题 | 截图分析当前游戏画面，必要时裁剪原图细节，最多重截一次\n/search 你的问题 | 深度思考并实时联网检索，不读写网页缓存；游戏状态使用本次即时查询，不参考旧对话。最多4次联网、12次游戏明细查询和3轮工具往返，检索阶段约25秒；资料充分或重复时提前收尾，以约一分钟完成为目标。超时返回已完成部分或资料不足说明，可取消。来源编号支持悬停查看网址，问答仍保存在当前存档。\n/help 你的问题 | 询问本 Mod 的功能、限制或操作方法。例如：\n/help 如何配置 API Key？\n/help 这个 Mod 能自动浇水吗？\n/help 对话记录保存在哪里？")
    };
}
